script:
// Client Script for Purchase Invoice
// This script automatically fills the pdf_file field ONLY with NextCloud public share links

frappe.ui.form.on('Purchase Invoice', {
    refresh: function(frm) {
        // Only try to fill if the field exists, is empty, and doc is saved
        if (frm.fields_dict.pdf_file && !frm.doc.pdf_file && !frm.doc.__islocal) {
            setTimeout(() => {
                fill_pdf_field_from_nextcloud_only(frm);
            }, 1500);
        }
    },

    after_save: function(frm) {
        // Only try to fill if the field exists and is empty
        if (frm.fields_dict.pdf_file && !frm.doc.pdf_file) {
            setTimeout(() => {
                fill_pdf_field_from_nextcloud_only(frm);
            }, 2500);
        }
    }
});

function fill_pdf_field_from_nextcloud_only(frm) {
    // Double check conditions before proceeding
    if (!frm.fields_dict.pdf_file || frm.doc.pdf_file || frm.doc.__islocal) {
        return;
    }

    // Query for PDF files that are uploaded to NextCloud
    frappe.db.get_list('File', {
        filters: {
            attached_to_doctype: frm.doctype,
            attached_to_name: frm.docname,
            file_name: ['like', '%.pdf'],
            uploaded_to_nextcloud: 1  // Only files uploaded to NextCloud
        },
        fields: ['name', 'file_url', 'file_name', 'share_link', 'uploaded_to_nextcloud'],
        order_by: 'creation desc',
        limit: 10
    }).then(files => {
        if (!files || files.length === 0) {
            return;
        }

        // Find the first valid NextCloud URL
        for (let file of files) {
            let url_to_use = null;

            // Check share_link first (this is the NextCloud public share link)
            if (file.share_link &&
                typeof file.share_link === 'string' &&
                file.share_link.startsWith('http') &&
                !file.share_link.includes('/files/') &&
                !file.share_link.includes('/private/')) {
                url_to_use = file.share_link;
            }
            // Then check file_url as fallback
            else if (file.file_url &&
                     typeof file.file_url === 'string' &&
                     file.file_url.startsWith('http') &&
                     !file.file_url.includes('/files/') &&
                     !file.file_url.includes('/private/') &&
                     !file.file_url.includes(window.location.hostname)) { // Exclude local domain
                url_to_use = file.file_url;
            }

            // If we found a valid NextCloud URL, use it
            if (url_to_use) {
                frm.set_value('pdf_file', url_to_use);
                frappe.show_alert({
                    message: __('PDF field updated with NextCloud link'),
                    indicator: 'green'
                }, 5);
                return; // Stop after first valid URL
            }
        }
    }).catch(err => {
        console.error("Error fetching NextCloud PDFs:", err);
    });
}

// Add manual button only
frappe.ui.form.on('Purchase Invoice', {
    refresh: function(frm) {
        if (frm.fields_dict.pdf_file && !frm.doc.__islocal) {
            frm.add_custom_button(__('Fill PDF from NextCloud'), function() {
                // Clear field if it contains a local path
                if (frm.doc.pdf_file &&
                    (frm.doc.pdf_file.includes('/files/') ||
                     frm.doc.pdf_file.includes('/private/') ||
                     !frm.doc.pdf_file.startsWith('http'))) {
                    frm.set_value('pdf_file', '');
                }

                // Wait a bit then try to fill
                setTimeout(() => {
                    fill_pdf_field_from_nextcloud_only(frm);
                }, 500);
            }, __('Actions'));
        }
    }
});
